        return False
    path = value.strip().replace("\\", "/")
    if path.startswith("/") or "/../" in f"/{path}/" or "/./" in f"/{path}/":
        return False
    return any(path.startswith(prefix) for prefix in PROMOTION_PATH_PREFIXES)

