def _status_has_token(status: str, token: str) -> bool:
    tokens = {part for part in re.split(r"[^a-z0-9]+", status.lower()) if part}
    if not tokens:
        return False
    if token == "blocked" and ("unblocked" in tokens or tokens == {"not", "blocked"}):
        return False
    return token in tokens

