) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    term = _text(value.get("term"))
    ontology_ref = _text(value.get("ontology_ref"))
    if not term or not ontology_ref:
        return [], [
            _finding(
                finding_id="term_binding_value_incomplete",
                severity="review_required",
                message="bind_existing_term decisions require term and ontology_ref.",
                evidence={
                    "request_id": context["request_id"],
                    "term": term,
                    "ontology_ref": ontology_ref,
                },
            )
        ]
    decision = _base_decision(
        context,
        index=index,
        decision_type="bind_existing_term",
    )
    decision.update(
        {
            "term": term,
            "ontology_ref": ontology_ref,
            "source_value": _public_safe(value),
        }
    )
    return [decision], []

def _ontology_answer_fingerprint(answers: list[dict[str, Any]]) -> str:
    projection: list[dict[str, Any]] = []
    for answer in answers:
        context = _request_context(answer)
        if context["request_kind"] != "ontology_gap":
            continue
        projection.append(
            {
                "request_id": context["request_id"],
                "answer_kind": context["source_answer_kind"],
                "status": context["source_answer_status"],
                "target_artifact": context["target_artifact"],
                "target_ref": context["target_ref"],
                "value": _public_safe(answer.get("value")),
            }
        )
    encoded = json.dumps(projection, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return f"sha256:{hashlib.sha256(encoded).hexdigest()}"

def path_matches_root(path_text: str, root_text: str) -> bool:
    path = str(path_text).strip()
    root = str(root_text).strip()
    if not path or not root:
        return False
    if root.endswith("/"):
        return path.startswith(root)
    return path == root or path.startswith(root.rstrip("/") + "/")

