def _safe_string(value: str) -> str:
    lowered = value.lower()
    if any(marker.lower() in lowered for marker in PRIVATE_PATH_MARKERS):
        digest = hashlib.sha256(value.encode("utf-8")).hexdigest()[:16]
        return f"redacted-local-ref:{digest}"
    return value

