def git_head_commit(cwd: Path = ROOT) -> str:
    result = subprocess.run(
        ["git", "rev-parse", "HEAD"],
        cwd=cwd,
        capture_output=True,
        text=True,
        check=False,
    )
    if result.returncode != 0:
        return ""
    return result.stdout.strip()

def graph_backlog_priority(
    *,
    next_gap: str,
    status: str,
    review_state: str,
    severity: str = "",
) -> str:
    severity_priority = {"critical": "high", "high": "high", "medium": "medium", "low": "low"}
    if severity in severity_priority:
        return severity_priority[severity]
    if next_gap == "collect_metrics_adoption_feedback":
        return "low"
    if review_state in {"ready_for_review", "review_visible", "adoption_visible", "review_due"}:
        return "high"
    if (
        status == "accepted_risk_recorded"
        or next_gap == "review_accepted_risk_when_context_changes"
    ):
        return "info"
    if "blocked" in status or next_gap.startswith("isolate_"):
        return "high"
    if next_gap.startswith("review_") or next_gap in {"resolve_review_gate", "resolve_split_gate"}:
        return "high"
    if next_gap in {
        "attach_trace_contract",
        "attach_evidence_contract",
        "attach_promotion_trace",
        "runtime_realization",
        "validation_closure",
        "reobservation",
        "repair_review_feedback_record",
    }:
        return "medium"
    if next_gap.startswith("attach_review_feedback"):
        return "medium"
    return "low"

