def quiet_progress_windows_for_reasoning(reasoning_effort: str) -> int:
    """Allow extra quiet windows for default and long-form reasoning modes."""
    if reasoning_effort in QUIET_PROGRESS_REASONING_EFFORTS:
        return XHIGH_QUIET_PROGRESS_WINDOWS
    return 0

def render_yaml_document(data: dict[str, Any]) -> str:
    if yaml is None:
        raise RuntimeError("PyYAML is required to render SpecPM export bundles")
    rendered = yaml.safe_dump(
        data,
        sort_keys=False,
        allow_unicode=True,
        default_flow_style=False,
        width=100,
    )
    if not rendered.endswith("\n"):
        rendered += "\n"
    return rendered

def repo_relative_prompt_extension_path(path_value: str) -> str:
    candidate_text = str(path_value or "").strip()
    if not candidate_text:
        raise ValueError("supervisor prompt extension path must be non-empty")

    candidate = Path(candidate_text).expanduser()
    resolved = candidate.resolve() if candidate.is_absolute() else (ROOT / candidate).resolve()
    try:
        relpath = resolved.relative_to(ROOT.resolve()).as_posix()
    except ValueError as exc:
        raise ValueError(
            "supervisor prompt extension file must stay inside this repository"
        ) from exc

    approved_roots = [
        str(root).strip().rstrip("/")
        for root in SUPERVISOR_PROMPT_POLICY.get("approved_prompt_roots", [])
        if str(root).strip()
    ]
    if not any(relpath == root or relpath.startswith(f"{root}/") for root in approved_roots):
        raise ValueError(
            "supervisor prompt extension file must stay under approved prompt roots: "
            + ", ".join(approved_roots)
        )
    return relpath

