    if status == "published" or summary.get("published") is True:
        return "published"
    if publication.get("dry_run") is True or status == "dry_run":
        return "dry_run"
    if _int(summary.get("error_count")) > 0 or "failed" in status:
        return "failed"
    if "blocked" in status:
